create table if not exists rooms (id uuid primary key default gen_random_uuid(), code text unique not null, status text not null default 'lobby', current_player_id uuid, round int not null default 1, created_at timestamptz not null default now());
create table if not exists players (id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete cascade, name text not null, avatar text, cash int not null default 1500, position int not null default 0, is_host boolean not null default false, joined_at timestamptz not null default now());
create table if not exists properties (id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete cascade, board_index int not null, owner_id uuid references players(id) on delete set null, price int, group_name text);
create table if not exists game_events (id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete cascade, player_id uuid references players(id) on delete set null, event_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists trades (id uuid primary key default gen_random_uuid(), room_id uuid references rooms(id) on delete cascade, from_player uuid references players(id), to_player uuid references players(id), offer jsonb not null, status text not null default 'pending', created_at timestamptz not null default now());
